<?php declare(strict_types=1); ?>
<!doctype html><html lang="<?= e(\App\Core\Translator::locale()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e(villa_ui('Ev sahipleri')) ?></title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1050px;margin:35px auto;padding:0 18px}table{width:100%;border-collapse:collapse;background:white;border-radius:13px;overflow:hidden}td,th{text-align:left;padding:14px;border-bottom:1px solid #edf0ed;font-size:14px}button{border:0;background:#176b50;color:white;padding:9px 12px;border-radius:8px;font-weight:700}.tag{background:#eef4ef;padding:5px 8px;border-radius:15px}
/* Consistent admin links and actions */
a{color:#176b50;text-decoration:none;transition:color .18s ease,background-color .18s ease,border-color .18s ease}a:hover{color:#104c39;text-decoration:none}td a:not([class]),.table-wrap a:not([class]){display:inline-flex;align-items:center;justify-content:center;padding:7px 11px;border:1px solid #dce9e0;border-radius:8px;background:#f5faf6;color:#176b50;font-size:12px;font-weight:750;white-space:nowrap}td a:not([class]):hover,.table-wrap a:not([class]):hover{background:#eaf4ee;border-color:#b9d8c4}button,input[type=submit]{cursor:pointer;font:inherit}button{transition:filter .18s ease,transform .18s ease}button:hover,input[type=submit]:hover{filter:brightness(.96)}
</style></head><body><main class="wrap"><h1><?= e(villa_ui('Ev sahibi başvuruları')) ?></h1><table><thead><tr><th><?= e(villa_ui('İşletme')) ?></th><th><?= e(villa_ui('Hesap')) ?></th><th><?= e(villa_ui('Telefon')) ?></th><th><?= e(villa_ui('Komisyon')) ?></th><th><?= e(villa_ui('Durum')) ?></th><th><?= e(villa_ui('İşlem')) ?></th></tr></thead><tbody><?php foreach($vendors as $v): ?><tr><td><?= e($v['business_name']) ?></td><td><?= e($v['username']) ?><br><?= e($v['email']) ?></td><td><?= e($v['phone']) ?></td><td><form method="post" action="/admin/vendors/commission"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$v['id'] ?>"><input type="number" min="0" max="50" step=".1" name="commission_rate" value="<?= e($v['commission_rate']??'') ?>" placeholder="<?= e(villa_ui('Varsayılan')) ?>" style="width:90px"><button type="submit"><?= e(villa_ui('Komisyon')) ?></button></form></td><td><span class="tag"><?= e($v['status']) ?></span></td><td><?php if($v['status']!=='approved'): ?><form method="post" action="/admin/vendors/approve"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$v['id'] ?>"><button type="submit"><?= e(villa_ui('Onayla')) ?></button></form><?php endif; ?><?php if($v['status']==='pending'): ?><form method="post" action="/admin/vendors/reject" onsubmit="return confirm(<?= e(json_encode(villa_ui('Bu başvuruyu reddetmek istiyor musunuz?'))) ?>)"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$v['id'] ?>"><button type="submit"><?= e(villa_ui('Reddet')) ?></button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$vendors): ?><tr><td colspan="6"><?= e(villa_ui('Başvuru bulunmuyor.')) ?></td></tr><?php endif; ?></tbody></table></main></body></html>